  1→// Package settings provides configuration loading for Entire.
  2→// This package is separate from cli to allow strategy package to import it
  3→// without creating an import cycle (cli imports strategy).
  4→package settings
  5→
  6→import (
  7→	"bytes"
  8→	"context"
  9→	"encoding/json"
 10→	"fmt"
 11→	"io"
 12→	"os"
 13→	"path/filepath"
 14→
 15→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 16→	"github.com/entireio/cli/cmd/entire/cli/paths"
 17→)
 18→
 19→const (
 20→	// EntireSettingsFile is the path to the Entire settings file
 21→	EntireSettingsFile = ".entire/settings.json"
 22→	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
 23→	EntireSettingsLocalFile = ".entire/settings.local.json"
 24→)
 25→
 26→// EntireSettings represents the .entire/settings.json configuration
 27→type EntireSettings struct {
 28→
 29→	// Enabled indicates whether Entire is active. When false, CLI commands
 30→	// show a disabled message and hooks exit silently. Defaults to true.
 31→	Enabled bool `json:"enabled"`
 32→
 33→	// LocalDev indicates whether to use "go run" instead of the "entire" binary
 34→	// This is used for development when the binary is not installed
 35→	LocalDev bool `json:"local_dev,omitempty"`
 36→
 37→	// LogLevel sets the logging verbosity (debug, info, warn, error).
 38→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
 39→	// Defaults to "info".
 40→	LogLevel string `json:"log_level,omitempty"`
 41→
 42→	// StrategyOptions contains strategy-specific configuration
 43→	StrategyOptions map[string]any `json:"strategy_options,omitempty"`
 44→
 45→	// Telemetry controls anonymous usage analytics.
 46→	// nil = not asked yet (show prompt), true = opted in, false = opted out
 47→	Telemetry *bool `json:"telemetry,omitempty"`
 48→
 49→	// Deprecated: no longer used. Exists to tolerate old settings files
 50→	// that still contain "strategy": "auto-commit" or similar.
 51→	Strategy string `json:"strategy,omitempty"`
 52→}
 53→
 54→// Load loads the Entire settings from .entire/settings.json,
 55→// then applies any overrides from .entire/settings.local.json if it exists.
 56→// Returns default settings if neither file exists.
 57→// Works correctly from any subdirectory within the repository.
 58→func Load(ctx context.Context) (*EntireSettings, error) {
 59→	// Get absolute paths for settings files
 60→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
 61→	if err != nil {
 62→		settingsFileAbs = EntireSettingsFile // Fallback to relative
 63→	}
 64→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
 65→	if err != nil {
 66→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
 67→	}
 68→
 69→	// Load base settings
 70→	settings, err := loadFromFile(settingsFileAbs)
 71→	if err != nil {
 72→		return nil, fmt.Errorf("reading settings file: %w", err)
 73→	}
 74→
 75→	// Apply local overrides if they exist
 76→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
 77→	if err != nil {
 78→		if !os.IsNotExist(err) {
 79→			return nil, fmt.Errorf("reading local settings file: %w", err)
 80→		}
 81→		// Local file doesn't exist, continue without overrides
 82→	} else {
 83→		if err := mergeJSON(settings, localData); err != nil {
 84→			return nil, fmt.Errorf("merging local settings: %w", err)
 85→		}
 86→	}
 87→
 88→	return settings, nil
 89→}
 90→
 91→// LoadFromFile loads settings from a specific file path without merging local overrides.
 92→// Returns default settings if the file doesn't exist.
 93→// Use this when you need to display individual settings files separately.
 94→func LoadFromFile(filePath string) (*EntireSettings, error) {
 95→	return loadFromFile(filePath)
 96→}
 97→
 98→// loadFromFile loads settings from a specific file path.
 99→// Returns default settings if the file doesn't exist.
100→func loadFromFile(filePath string) (*EntireSettings, error) {
101→	settings := &EntireSettings{
102→		Enabled: true, // Default to enabled
103→	}
104→
105→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
106→	if err != nil {
107→		if os.IsNotExist(err) {
108→			return settings, nil
109→		}
110→		return nil, fmt.Errorf("%w", err)
111→	}
112→
113→	dec := json.NewDecoder(bytes.NewReader(data))
114→	dec.DisallowUnknownFields()
115→	if err := dec.Decode(settings); err != nil {
116→		return nil, fmt.Errorf("parsing settings file: %w", err)
117→	}
118→
119→	return settings, nil
120→}
121→
122→// mergeJSON merges JSON data into existing settings.
123→// Only non-zero values from the JSON override existing settings.
124→func mergeJSON(settings *EntireSettings, data []byte) error {
125→	// First, validate that there are no unknown keys using strict decoding
126→	dec := json.NewDecoder(bytes.NewReader(data))
127→	dec.DisallowUnknownFields()
128→	var temp EntireSettings
129→	if err := dec.Decode(&temp); err != nil {
130→		return fmt.Errorf("parsing JSON: %w", err)
131→	}
132→
133→	// Parse into a map to check which fields are present
134→	var raw map[string]json.RawMessage
135→	if err := json.Unmarshal(data, &raw); err != nil {
136→		return fmt.Errorf("parsing JSON: %w", err)
137→	}
138→
139→	// Override enabled if present
140→	if enabledRaw, ok := raw["enabled"]; ok {
141→		var e bool
142→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
143→			return fmt.Errorf("parsing enabled field: %w", err)
144→		}
145→		settings.Enabled = e
146→	}
147→
148→	// Override local_dev if present
149→	if localDevRaw, ok := raw["local_dev"]; ok {
150→		var ld bool
151→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
152→			return fmt.Errorf("parsing local_dev field: %w", err)
153→		}
154→		settings.LocalDev = ld
155→	}
156→
157→	// Override log_level if present and non-empty
158→	if logLevelRaw, ok := raw["log_level"]; ok {
159→		var ll string
160→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
161→			return fmt.Errorf("parsing log_level field: %w", err)
162→		}
163→		if ll != "" {
164→			settings.LogLevel = ll
165→		}
166→	}
167→
168→	// Merge strategy_options if present
169→	if optionsRaw, ok := raw["strategy_options"]; ok {
170→		var opts map[string]any
171→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
172→			return fmt.Errorf("parsing strategy_options field: %w", err)
173→		}
174→		if settings.StrategyOptions == nil {
175→			settings.StrategyOptions = opts
176→		} else {
177→			for k, v := range opts {
178→				settings.StrategyOptions[k] = v
179→			}
180→		}
181→	}
182→
183→	// Override telemetry if present
184→	if telemetryRaw, ok := raw["telemetry"]; ok {
185→		var t bool
186→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
187→			return fmt.Errorf("parsing telemetry field: %w", err)
188→		}
189→		settings.Telemetry = &t
190→	}
191→
192→	return nil
193→}
