195→// IsSetUp returns true if Entire has been set up in the current repository.
196→// This checks if .entire/settings.json exists.
197→// Use this to avoid creating files/directories in repos where Entire was never enabled.
198→func IsSetUp(ctx context.Context) bool {
199→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
200→	if err != nil {
201→		return false
202→	}
203→	_, err = os.Stat(settingsFileAbs)
204→	return err == nil
205→}
206→
207→// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
208→// This checks if .entire/settings.json exists AND has enabled: true.
209→// Use this for hooks that should be no-ops when Entire is not active.
210→func IsSetUpAndEnabled(ctx context.Context) bool {
211→	if !IsSetUp(ctx) {
212→		return false
213→	}
214→	s, err := Load(ctx)
215→	if err != nil {
216→		return false
217→	}
218→	return s.Enabled
219→}
220→
221→// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
222→// Returns false by default if settings cannot be loaded or the key is missing.
223→func IsSummarizeEnabled(ctx context.Context) bool {
224→	settings, err := Load(ctx)
225→	if err != nil {
226→		return false
227→	}
228→	return settings.IsSummarizeEnabled()
229→}
230→
231→// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
232→func (s *EntireSettings) IsSummarizeEnabled() bool {
233→	if s.StrategyOptions == nil {
234→		return false
235→	}
236→	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
237→	if !ok {
238→		return false
239→	}
240→	enabled, ok := summarizeOpts["enabled"].(bool)
241→	if !ok {
242→		return false
243→	}
244→	return enabled
245→}
246→
247→// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
248→// Returns true if push_sessions is explicitly set to false.
249→func (s *EntireSettings) IsPushSessionsDisabled() bool {
250→	if s.StrategyOptions == nil {
251→		return false
252→	}
253→	val, exists := s.StrategyOptions["push_sessions"]
254→	if !exists {
255→		return false
256→	}
257→	if boolVal, ok := val.(bool); ok {
258→		return !boolVal // disabled = !push_sessions
259→	}
260→	return false
261→}
262→
263→// FilesWithDeprecatedStrategy returns the relative paths of settings files
264→// that still contain the deprecated "strategy" field.
265→func FilesWithDeprecatedStrategy(ctx context.Context) []string {
266→	var files []string
267→	for _, rel := range []string{EntireSettingsFile, EntireSettingsLocalFile} {
268→		abs, err := paths.AbsPath(ctx, rel)
269→		if err != nil {
270→			abs = rel // Fallback to relative
271→		}
272→		s, err := LoadFromFile(abs)
273→		if err != nil || s.Strategy == "" {
274→			continue
275→		}
276→		files = append(files, rel)
277→	}
278→	return files
279→}
280→
281→// WriteDeprecatedStrategyWarnings writes user-friendly deprecation warnings
282→// for each settings file that still contains the "strategy" field.
283→// Returns true if any warnings were written.
284→func WriteDeprecatedStrategyWarnings(ctx context.Context, w io.Writer) bool {
285→	files := FilesWithDeprecatedStrategy(ctx)
286→	for _, f := range files {
287→		fmt.Fprintf(w, "Note: \"%s\" in %s is no longer needed and can be removed. 'manual-commit' is now the only supported strategy.\n", "strategy", f)
288→	}
289→	return len(files) > 0
290→}
291→
292→// Save saves the settings to .entire/settings.json.
293→func Save(ctx context.Context, settings *EntireSettings) error {
294→	return saveToFile(ctx, settings, EntireSettingsFile)
295→}
296→
297→// SaveLocal saves the settings to .entire/settings.local.json.
298→func SaveLocal(ctx context.Context, settings *EntireSettings) error {
299→	return saveToFile(ctx, settings, EntireSettingsLocalFile)
300→}
301→
302→// saveToFile saves settings to the specified file path.
303→func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
304→	// Get absolute path for the file
305→	filePathAbs, err := paths.AbsPath(ctx, filePath)
306→	if err != nil {
307→		filePathAbs = filePath // Fallback to relative
308→	}
309→
310→	// Ensure directory exists
311→	dir := filepath.Dir(filePathAbs)
312→	if err := os.MkdirAll(dir, 0o750); err != nil {
313→		return fmt.Errorf("creating settings directory: %w", err)
314→	}
315→
316→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
317→	if err != nil {
318→		return fmt.Errorf("marshaling settings: %w", err)
319→	}
320→
321→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
322→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
323→		return fmt.Errorf("writing settings file: %w", err)
324→	}
325→	return nil
326→}
