  1→package cli
  2→
  3→import (
  4→	"context"
  5→	"fmt"
  6→	"strings"
  7→
  8→	"github.com/entireio/cli/cmd/entire/cli/agent"
  9→	"github.com/entireio/cli/cmd/entire/cli/settings"
 10→	"github.com/entireio/cli/cmd/entire/cli/strategy"
 11→
 12→	// Import claudecode to register the agent
 13→	_ "github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
 14→)
