 16→// Package-level aliases to avoid shadowing the settings package with local variables named "settings".
 17→const (
 18→	EntireSettingsFile      = settings.EntireSettingsFile
 19→	EntireSettingsLocalFile = settings.EntireSettingsLocalFile
 20→)
 21→
 22→// EntireSettings is an alias for settings.EntireSettings.
 23→type EntireSettings = settings.EntireSettings
 24→
 25→// LoadEntireSettings loads the Entire settings from .entire/settings.json,
 26→// then applies any overrides from .entire/settings.local.json if it exists.
 27→// Returns default settings if neither file exists.
 28→// Works correctly from any subdirectory within the repository.
 29→func LoadEntireSettings(ctx context.Context) (*settings.EntireSettings, error) {
 30→	s, err := settings.Load(ctx)
 31→	if err != nil {
 32→		return nil, fmt.Errorf("loading settings: %w", err)
 33→	}
 34→	return s, nil
 35→}
 36→
 37→// SaveEntireSettings saves the Entire settings to .entire/settings.json.
 38→func SaveEntireSettings(ctx context.Context, s *settings.EntireSettings) error {
 39→	if err := settings.Save(ctx, s); err != nil {
 40→		return fmt.Errorf("saving settings: %w", err)
 41→	}
 42→	return nil
 43→}
 44→
 45→// SaveEntireSettingsLocal saves the Entire settings to .entire/settings.local.json.
 46→func SaveEntireSettingsLocal(ctx context.Context, s *settings.EntireSettings) error {
 47→	if err := settings.SaveLocal(ctx, s); err != nil {
 48→		return fmt.Errorf("saving local settings: %w", err)
 49→	}
 50→	return nil
 51→}
 52→
 53→// IsEnabled returns whether Entire is currently enabled.
 54→// Returns true by default if settings cannot be loaded.
 55→func IsEnabled(ctx context.Context) (bool, error) {
 56→	s, err := settings.Load(ctx)
 57→	if err != nil {
 58→		return true, err //nolint:wrapcheck // already present in codebase
 59→	}
 60→	return s.Enabled, nil
 61→}
 62→
 63→// GetStrategy returns the configured strategy instance.
 64→// Falls back to default if the configured strategy is not found.
 65→//
 66→
 67→func GetStrategy(_ context.Context) strategy.Strategy {
 68→	return strategy.NewManualCommitStrategy()
 69→}
 70→
 71→// GetLogLevel returns the configured log level from settings.
 72→// Returns empty string if not configured (caller should use default).
 73→// Note: ENTIRE_LOG_LEVEL env var takes precedence; check it first.
 74→func GetLogLevel() string {
 75→	s, err := settings.Load(context.TODO()) //nolint:contextcheck // Called as a callback via SetLogLevelGetter, no ctx available
 76→	if err != nil {
 77→		return ""
 78→	}
 79→	return s.LogLevel
 80→}
 81→
 82→// GetAgentsWithHooksInstalled returns names of agents that have hooks installed.
 83→func GetAgentsWithHooksInstalled(ctx context.Context) []agent.AgentName {
 84→	var installed []agent.AgentName
 85→	for _, name := range agent.List() {
 86→		ag, err := agent.Get(name)
 87→		if err != nil {
 88→			continue
 89→		}
 90→		if hs, ok := ag.(agent.HookSupport); ok && hs.AreHooksInstalled(ctx) {
 91→			installed = append(installed, name)
 92→		}
 93→	}
 94→	return installed
 95→}
 96→
 97→// JoinAgentNames joins agent names into a comma-separated string.
 98→func JoinAgentNames(names []agent.AgentName) string {
 99→	strs := make([]string, len(names))
100→	for i, n := range names {
101→		strs[i] = string(n)
102→	}
103→	return strings.Join(strs, ",")
104→}
