 156→// runEnableInteractive runs the interactive enable flow.
 157→// agents must be provided by the caller (via detectOrSelectAgent).
 158→func runEnableInteractive(ctx context.Context, w io.Writer, agents []agent.Agent, localDev, useLocalSettings, useProjectSettings, forceHooks, skipPushSessions, telemetry bool) error {
 159→	// Uninstall hooks for agents that were previously active but are no longer selected
 160→	if err := uninstallDeselectedAgentHooks(ctx, w, agents); err != nil {
 161→		return fmt.Errorf("failed to clean up deselected agents: %w", err)
 162→	}
 163→
 164→	// Setup agent hooks for all selected agents
 165→	for _, ag := range agents {
 166→		if _, err := setupAgentHooks(ctx, ag, localDev, forceHooks); err != nil {
 167→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
 168→		}
 169→	}
 170→
 171→	// Setup .entire directory
 172→	if _, err := setupEntireDirectory(ctx); err != nil {
 173→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 174→	}
 175→
 176→	// Load existing settings to preserve other options (like strategy_options.push)
 177→	settings, err := LoadEntireSettings(ctx)
 178→	if err != nil {
 179→		// If we can't load, start with defaults
 180→		settings = &EntireSettings{}
 181→	}
 182→	// Update the specific fields
 183→	settings.LocalDev = localDev
 184→	settings.Enabled = true
 185→
 186→	// Set push_sessions option if --skip-push-sessions flag was provided
 187→	if skipPushSessions {
 188→		if settings.StrategyOptions == nil {
 189→			settings.StrategyOptions = make(map[string]interface{})
 190→		}
 191→		settings.StrategyOptions["push_sessions"] = false
 192→	}
 193→
 194→	// Determine which settings file to write to
 195→	// First run always creates settings.json (no prompt)
 196→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 197→	if err != nil {
 198→		entireDirAbs = paths.EntireDir // Fallback to relative
 199→	}
 200→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
 201→
 202→	if showNotification {
 203→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
 204→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
 205→	}
 206→
 207→	// Helper to save settings to the appropriate file
 208→	saveSettings := func() error {
 209→		if shouldUseLocal {
 210→			return SaveEntireSettingsLocal(ctx, settings)
 211→		}
 212→		return SaveEntireSettings(ctx, settings)
 213→	}
 214→
 215→	// Save settings before telemetry prompt so config is persisted even if the user cancels
 216→	if err := saveSettings(); err != nil {
 217→		return fmt.Errorf("failed to save settings: %w", err)
 218→	}
 219→
 220→	if _, err := strategy.InstallGitHook(ctx, true, localDev); err != nil {
 221→		return fmt.Errorf("failed to install git hooks: %w", err)
 222→	}
 223→	strategy.CheckAndWarnHookManagers(ctx, w, localDev)
 224→	fmt.Fprintln(w, "✓ Hooks installed")
 225→
 226→	configDisplay := configDisplayProject
 227→	if shouldUseLocal {
 228→		configDisplay = configDisplayLocal
 229→	}
 230→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
 231→
 232→	// Ask about telemetry consent (only if not already asked)
 233→	fmt.Fprintln(w)
 234→	if err := promptTelemetryConsent(settings, telemetry); err != nil {
 235→		return fmt.Errorf("telemetry consent: %w", err)
 236→	}
 237→	// Save again to persist telemetry choice
 238→	if err := saveSettings(); err != nil {
 239→		return fmt.Errorf("failed to save settings: %w", err)
 240→	}
 241→
 242→	if err := strategy.EnsureSetup(ctx); err != nil {
 243→		return fmt.Errorf("failed to setup strategy: %w", err)
 244→	}
 245→
 246→	fmt.Fprintln(w, "\nReady.")
 247→
 248→	return nil
 249→}
