 310→// uninstallDeselectedAgentHooks removes hooks for agents that were previously
 311→// installed but are not in the selected list. This handles the case where a user
 312→// re-runs `entire enable` and deselects an agent.
 313→func uninstallDeselectedAgentHooks(ctx context.Context, w io.Writer, selectedAgents []agent.Agent) error {
 314→	installedNames := GetAgentsWithHooksInstalled(ctx)
 315→	if len(installedNames) == 0 {
 316→		return nil
 317→	}
 318→
 319→	selectedSet := make(map[agent.AgentName]struct{}, len(selectedAgents))
 320→	for _, ag := range selectedAgents {
 321→		selectedSet[ag.Name()] = struct{}{}
 322→	}
 323→
 324→	var errs []error
 325→	for _, name := range installedNames {
 326→		if _, selected := selectedSet[name]; selected {
 327→			continue
 328→		}
 329→		ag, err := agent.Get(name)
 330→		if err != nil {
 331→			continue
 332→		}
 333→		hookAgent, ok := ag.(agent.HookSupport)
 334→		if !ok {
 335→			continue
 336→		}
 337→		if err := hookAgent.UninstallHooks(ctx); err != nil {
 338→			errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
 339→		} else {
 340→			fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
 341→		}
 342→	}
 343→	return errors.Join(errs...)
 344→}
