 346→// setupAgentHooks sets up hooks for a given agent.
 347→// Returns the number of hooks installed (0 if already installed).
 348→func setupAgentHooks(ctx context.Context, ag agent.Agent, localDev, forceHooks bool) (int, error) {
 349→	hookAgent, ok := ag.(agent.HookSupport)
 350→	if !ok {
 351→		return 0, fmt.Errorf("agent %s does not support hooks", ag.Name())
 352→	}
 353→
 354→	count, err := hookAgent.InstallHooks(ctx, localDev, forceHooks)
 355→	if err != nil {
 356→		return 0, fmt.Errorf("failed to install %s hooks: %w", ag.Name(), err)
 357→	}
 358→
 359→	return count, nil
