 362→// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
 363→// Returns the detected/selected agents and any error.
 364→//
 365→// On first run (no hooks installed):
 366→//   - Single detected agent: used automatically
 367→//   - Multiple/no detected agents: interactive multi-select prompt
 368→//
 369→// On re-run (hooks already installed):
 370→//   - Always shows the interactive multi-select
 371→//   - Pre-selects only agents that have hooks installed (respects prior deselection)
 372→//
 373→// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
 374→// It receives available agent names and returns the selected names.
 375→func detectOrSelectAgent(ctx context.Context, w io.Writer, selectFn func(available []string) ([]string, error)) ([]agent.Agent, error) {
 376→	// Check for agents with hooks already installed (re-run detection)
 377→	installedAgentNames := GetAgentsWithHooksInstalled(ctx)
 378→	hasInstalledHooks := len(installedAgentNames) > 0
 379→
 380→	// Try auto-detection
 381→	detected := agent.DetectAll(ctx)
 382→
 383→	// First run: use existing auto-detect shortcuts
 384→	if !hasInstalledHooks {
 385→		switch {
 386→		case len(detected) == 1:
 387→			fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
 388→			return detected, nil
 389→
 390→		case len(detected) > 1:
 391→			agentTypes := make([]string, 0, len(detected))
 392→			for _, ag := range detected {
 393→				agentTypes = append(agentTypes, string(ag.Type()))
 394→			}
 395→			fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
 396→			fmt.Fprintln(w)
 397→		}
 398→	}
 399→
 400→	// Check if we can prompt interactively
 401→	if !canPromptInteractively() {
 402→		if hasInstalledHooks {
 403→			// Re-run without TTY — keep currently installed agents
 404→			agents := make([]agent.Agent, 0, len(installedAgentNames))
 405→			for _, name := range installedAgentNames {
 406→				ag, err := agent.Get(name)
 407→				if err != nil {
 408→					continue
 409→				}
 410→				agents = append(agents, ag)
 411→			}
 412→			return agents, nil
 413→		}
 414→		if len(detected) > 0 {
 415→			return detected, nil
 416→		}
 417→		defaultAgent := agent.Default()
 418→		if defaultAgent == nil {
 419→			return nil, errors.New("no default agent available")
 420→		}
 421→		fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
 422→		return []agent.Agent{defaultAgent}, nil
 423→	}
 424→
 425→	if !hasInstalledHooks && len(detected) == 0 {
 426→		fmt.Fprintln(w, "No agent configuration detected (e.g., "+strings.Join(agent.StringList(), ", ")+").")
 427→		fmt.Fprintln(w, "This is normal - some agents don't require a config directory.")
 428→		fmt.Fprintln(w)
 429→	}
 430→
 431→	// Build pre-selection set.
 432→	// On re-run: only pre-select agents with hooks installed (respect prior deselection).
 433→	// On first run: pre-select all detected agents.
 434→	preSelectedSet := make(map[agent.AgentName]struct{})
 435→	if hasInstalledHooks {
 436→		for _, name := range installedAgentNames {
 437→			preSelectedSet[name] = struct{}{}
 438→		}
 439→	} else {
 440→		for _, ag := range detected {
 441→			preSelectedSet[ag.Name()] = struct{}{}
 442→		}
 443→	}
 444→
 445→	// Build options from registered agents
 446→	agentNames := agent.List()
 447→	options := make([]huh.Option[string], 0, len(agentNames))
 448→	for _, name := range agentNames {
 449→		ag, err := agent.Get(name)
 450→		if err != nil {
 451→			continue
 452→		}
 453→		// Only show agents that support hooks
 454→		if _, ok := ag.(agent.HookSupport); !ok {
 455→			continue
 456→		}
 457→		opt := huh.NewOption(string(ag.Type()), string(name))
 458→		if _, isPreSelected := preSelectedSet[name]; isPreSelected {
 459→			opt = opt.Selected(true)
 460→		}
 461→		options = append(options, opt)
 462→	}
 463→
 464→	if len(options) == 0 {
 465→		return nil, errors.New("no agents with hook support available")
 466→	}
 467→
 468→	// Collect available agent names for the selector
 469→	availableNames := make([]string, 0, len(options))
 470→	for _, opt := range options {
 471→		availableNames = append(availableNames, opt.Value)
 472→	}
 473→
 474→	var selectedAgentNames []string
 475→	if selectFn != nil {
 476→		var err error
 477→		selectedAgentNames, err = selectFn(availableNames)
 478→		if err != nil {
 479→			return nil, err
 480→		}
 481→		if len(selectedAgentNames) == 0 {
 482→			return nil, errors.New("no agents selected")
 483→		}
 484→	} else {
 485→		form := NewAccessibleForm(
 486→			huh.NewGroup(
 487→				huh.NewMultiSelect[string]().
 488→					Title("Which agents are you using?").
 489→					Description("Use space to select, enter to confirm.").
 490→					Options(options...).
 491→					Validate(func(selected []string) error {
 492→						if len(selected) == 0 {
 493→							return errors.New("please select at least one agent")
 494→						}
 495→						return nil
 496→					}).
 497→					Value(&selectedAgentNames),
 498→			),
 499→		)
 500→		if err := form.Run(); err != nil {
 501→			return nil, fmt.Errorf("agent selection cancelled: %w", err)
 502→		}
 503→	}
 504→
 505→	selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
 506→	for _, name := range selectedAgentNames {
 507→		selectedAgent, err := agent.Get(agent.AgentName(name))
 508→		if err != nil {
 509→			return nil, fmt.Errorf("failed to get selected agent %s: %w", name, err)
 510→		}
 511→		selectedAgents = append(selectedAgents, selectedAgent)
 512→	}
 513→
 514→	agentTypes := make([]string, 0, len(selectedAgents))
 515→	for _, ag := range selectedAgents {
 516→		agentTypes = append(agentTypes, string(ag.Type()))
 517→	}
 518→	fmt.Fprintf(w, "\nSelected agents: %s\n\n", strings.Join(agentTypes, ", "))
 519→	return selectedAgents, nil
 520→}
