 565→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
 566→// If strategyName is provided, it sets the strategy; otherwise uses default.
 567→func setupAgentHooksNonInteractive(ctx context.Context, w io.Writer, ag agent.Agent, localDev, forceHooks, skipPushSessions, telemetry bool) error {
 568→	agentName := ag.Name()
 569→	// Check if agent supports hooks
 570→	hookAgent, ok := ag.(agent.HookSupport)
 571→	if !ok {
 572→		return fmt.Errorf("agent %s does not support hooks", agentName)
 573→	}
 574→
 575→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
 576→
 577→	// Install agent hooks (agent hooks don't depend on settings)
 578→	installedHooks, err := hookAgent.InstallHooks(ctx, localDev, forceHooks)
 579→	if err != nil {
 580→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
 581→	}
 582→
 583→	// Setup .entire directory
 584→	if _, err := setupEntireDirectory(ctx); err != nil {
 585→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 586→	}
 587→
 588→	// Load existing settings to preserve other options (like strategy_options.push)
 589→	settings, err := LoadEntireSettings(ctx)
 590→	if err != nil {
 591→		// If we can't load, start with defaults
 592→		settings = &EntireSettings{}
 593→	}
 594→	settings.Enabled = true
 595→	if localDev {
 596→		settings.LocalDev = localDev
 597→	}
 598→
 599→	// Set push_sessions option if --skip-push-sessions flag was provided
 600→	if skipPushSessions {
 601→		if settings.StrategyOptions == nil {
 602→			settings.StrategyOptions = make(map[string]interface{})
 603→		}
 604→		settings.StrategyOptions["push_sessions"] = false
 605→	}
 606→
 607→	// Handle telemetry for non-interactive mode
 608→	// Note: if telemetry is nil (not configured), it defaults to disabled
 609→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 610→		f := false
 611→		settings.Telemetry = &f
 612→	}
 613→
 614→	if err := SaveEntireSettings(ctx, settings); err != nil {
 615→		return fmt.Errorf("failed to save settings: %w", err)
 616→	}
 617→
 618→	if _, err := strategy.InstallGitHook(ctx, true, localDev); err != nil {
 619→		return fmt.Errorf("failed to install git hooks: %w", err)
 620→	}
 621→	strategy.CheckAndWarnHookManagers(ctx, w, localDev)
 622→
 623→	if installedHooks == 0 {
 624→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
 625→		if ag.IsPreview() {
 626→			msg += " (Preview)"
 627→		}
 628→		fmt.Fprintf(w, "%s\n", msg)
 629→	} else {
 630→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
 631→		if ag.IsPreview() {
 632→			msg += " (Preview)"
 633→		}
 634→		fmt.Fprintf(w, "%s\n", msg)
 635→	}
 636→
 637→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
 638→
 639→	if err := strategy.EnsureSetup(ctx); err != nil {
 640→		return fmt.Errorf("failed to setup strategy: %w", err)
 641→	}
 642→
 643→	fmt.Fprintln(w, "\nReady.")
 644→
 645→	return nil
 646→}
