 912→// runUninstall completely removes Entire from the repository.
 913→func runUninstall(ctx context.Context, w, errW io.Writer, force bool) error {
 914→	// Check if we're in a git repository
 915→	if _, err := paths.WorktreeRoot(ctx); err != nil {
 916→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
 917→		return NewSilentError(errors.New("not a git repository"))
 918→	}
 919→
 920→	// Gather counts for display
 921→	sessionStateCount := countSessionStates(ctx)
 922→	shadowBranchCount := countShadowBranches(ctx)
 923→	gitHooksInstalled := strategy.IsGitHookInstalled(ctx)
 924→	agentsWithInstalledHooks := GetAgentsWithHooksInstalled(ctx)
 925→	entireDirExists := checkEntireDirExists(ctx)
 926→
 927→	// Check if there's anything to uninstall
 928→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
 929→		shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
 930→		fmt.Fprintln(w, "Entire is not installed in this repository.")
 931→		return nil
 932→	}
 933→
 934→	// Show confirmation prompt unless --force
 935→	if !force {
 936→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
 937→		if entireDirExists {
 938→			fmt.Fprintln(w, "  - .entire/ directory")
 939→		}
 940→		if gitHooksInstalled {
 941→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
 942→		}
 943→		if sessionStateCount > 0 {
 944→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
 945→		}
 946→		if shadowBranchCount > 0 {
 947→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
 948→		}
 949→		if len(agentsWithInstalledHooks) > 0 {
 950→			displayNames := make([]string, 0, len(agentsWithInstalledHooks))
 951→			for _, name := range agentsWithInstalledHooks {
 952→				if ag, err := agent.Get(name); err == nil {
 953→					displayNames = append(displayNames, string(ag.Type()))
 954→				}
 955→			}
 956→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
 957→		}
 958→		fmt.Fprintln(w)
 959→
 960→		var confirmed bool
 961→		form := NewAccessibleForm(
 962→			huh.NewGroup(
 963→				huh.NewConfirm().
 964→					Title("Are you sure you want to uninstall Entire?").
 965→					Affirmative("Yes, uninstall").
 966→					Negative("Cancel").
 967→					Value(&confirmed),
 968→			),
 969→		)
 970→
 971→		if err := form.Run(); err != nil {
 972→			return fmt.Errorf("confirmation cancelled: %w", err)
 973→		}
 974→
 975→		if !confirmed {
 976→			fmt.Fprintln(w, "Uninstall cancelled.")
 977→			return nil
 978→		}
 979→	}
 980→
 981→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
 982→
 983→	// 1. Remove agent hooks (lowest risk)
 984→	if err := removeAgentHooks(ctx, w); err != nil {
 985→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
 986→	}
 987→
 988→	// 2. Remove git hooks
 989→	removed, err := strategy.RemoveGitHook(ctx)
 990→	if err != nil {
 991→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
 992→	} else if removed > 0 {
 993→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
 994→	}
 995→
 996→	// 3. Remove session state files
 997→	statesRemoved, err := removeAllSessionStates(ctx)
 998→	if err != nil {
 999→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
1000→	} else if statesRemoved > 0 {
1001→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1002→	}
1003→
1004→	// 4. Remove .entire/ directory
1005→	if err := removeEntireDirectory(ctx); err != nil {
1006→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1007→	} else if entireDirExists {
1008→		fmt.Fprintln(w, "  Removed .entire directory")
1009→	}
1010→
1011→	// 5. Remove shadow branches
1012→	branchesRemoved, err := removeAllShadowBranches(ctx)
1013→	if err != nil {
1014→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1015→	} else if branchesRemoved > 0 {
1016→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
1017→	}
1018→
1019→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
1020→	return nil
1021→}
