1055→// removeAgentHooks removes hooks from all agents that support hooks.
1056→func removeAgentHooks(ctx context.Context, w io.Writer) error {
1057→	var errs []error
1058→	for _, name := range agent.List() {
1059→		ag, err := agent.Get(name)
1060→		if err != nil {
1061→			continue
1062→		}
1063→		hs, ok := ag.(agent.HookSupport)
1064→		if !ok {
1065→			continue
1066→		}
1067→		wasInstalled := hs.AreHooksInstalled(ctx)
1068→		if err := hs.UninstallHooks(ctx); err != nil {
1069→			errs = append(errs, err)
1070→		} else if wasInstalled {
1071→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1072→		}
1073→	}
1074→	return errors.Join(errs...)
1075→}
