1077→// removeAllSessionStates removes all session state files and the directory.
1078→func removeAllSessionStates(ctx context.Context) (int, error) {
1079→	store, err := session.NewStateStore(ctx)
1080→	if err != nil {
1081→		return 0, fmt.Errorf("failed to create state store: %w", err)
1082→	}
1083→
1084→	// Count states before removing
1085→	states, err := store.List(ctx)
1086→	if err != nil {
1087→		return 0, fmt.Errorf("failed to list session states: %w", err)
1088→	}
1089→	count := len(states)
1090→
1091→	// Remove the entire directory
1092→	if err := store.RemoveAll(); err != nil {
1093→		return 0, fmt.Errorf("failed to remove session states: %w", err)
1094→	}
1095→
1096→	return count, nil
1097→}
