1099→// removeEntireDirectory removes the .entire directory.
1100→func removeEntireDirectory(ctx context.Context) error {
1101→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
1102→	if err != nil {
1103→		entireDirAbs = paths.EntireDir
1104→	}
1105→	if err := os.RemoveAll(entireDirAbs); err != nil {
1106→		return fmt.Errorf("failed to remove .entire directory: %w", err)
1107→	}
1108→	return nil
1109→}
