 19→// NoDescription is the default description for sessions without one.
 20→const NoDescription = "No description"
 21→
 22→// Session represents a Claude Code session with its checkpoints.
 23→// A session is created when a user runs `claude` and tracks all changes
 24→// made during that interaction.
 25→type Session struct {
 26→	// ID is the unique session identifier (e.g., "2025-12-01-8f76b0e8-b8f1-4a87-9186-848bdd83d62e")
 27→	ID string
 28→
 29→	// Description is a human-readable summary of the session
 30→	// (typically the first prompt or derived from commit messages)
 31→	Description string
 32→
 33→	// Strategy is the name of the strategy that created this session
 34→	Strategy string
 35→
 36→	// StartTime is when the session was started
 37→	StartTime time.Time
 38→
 39→	// Checkpoints is the list of save points within this session
 40→	Checkpoints []Checkpoint
 41→}
 42→
 43→// Checkpoint represents a save point within a session.
 44→// Checkpoints can be either session-level (on Stop) or task-level (on subagent completion).
 45→type Checkpoint struct {
 46→	// CheckpointID is the stable 12-hex-char identifier for this checkpoint.
 47→	// Used to look up metadata at <id[:2]>/<id[2:]>/ on entire/checkpoints/v1 branch.
 48→	CheckpointID id.CheckpointID
 49→
 50→	// Message is the commit message or checkpoint description
 51→	Message string
 52→
 53→	// Timestamp is when this checkpoint was created
 54→	Timestamp time.Time
 55→
 56→	// IsTaskCheckpoint indicates if this is a task checkpoint (vs a session checkpoint)
 57→	IsTaskCheckpoint bool
 58→
 59→	// ToolUseID is the tool use ID for task checkpoints (empty for session checkpoints)
 60→	ToolUseID string
 61→}
 62→
 63→// ListSessions returns all sessions from the entire/checkpoints/v1 branch,
 64→// plus any additional sessions from strategies implementing SessionSource.
 65→// It automatically discovers all registered strategies and merges their sessions.
 66→func ListSessions(ctx context.Context) ([]Session, error) {
 67→	repo, err := OpenRepository(ctx)
 68→	if err != nil {
 69→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 70→	}
 71→
 72→	// Get checkpoints from the entire/checkpoints/v1 branch
 73→	checkpoints, err := ListCheckpoints(ctx)
 74→	if err != nil {
 75→		return nil, fmt.Errorf("failed to list checkpoints: %w", err)
 76→	}
 77→
 78→	// Group checkpoints by session ID
 79→	// For multi-session checkpoints, expand SessionIDs array so each session gets the checkpoint
 80→	sessionMap := make(map[string]*Session)
 81→	for _, cp := range checkpoints {
 82→		// Determine which session IDs this checkpoint belongs to
 83→		// Multi-session checkpoints have SessionIDs populated; single-session use SessionID
 84→		sessionIDs := cp.SessionIDs
 85→		if len(sessionIDs) == 0 {
 86→			sessionIDs = []string{cp.SessionID}
 87→		}
 88→
 89→		for _, sessionID := range sessionIDs {
 90→			if sessionID == "" {
 91→				continue
 92→			}
 93→
 94→			if existing, ok := sessionMap[sessionID]; ok {
 95→				existing.Checkpoints = append(existing.Checkpoints, Checkpoint{
 96→					CheckpointID:     cp.CheckpointID,
 97→					Message:          "Checkpoint: " + cp.CheckpointID.String(),
 98→					Timestamp:        cp.CreatedAt,
 99→					IsTaskCheckpoint: cp.IsTask,
100→					ToolUseID:        cp.ToolUseID,
101→				})
102→			} else {
103→				// Get description from the checkpoint tree
104→				description := getDescriptionForCheckpoint(repo, cp.CheckpointID)
105→
106→				sessionMap[sessionID] = &Session{
107→					ID:          sessionID,
108→					Description: description,
109→					Strategy:    "", // Will be set from metadata if available
110→					StartTime:   cp.CreatedAt,
111→					Checkpoints: []Checkpoint{{
112→						CheckpointID:     cp.CheckpointID,
113→						Message:          "Checkpoint: " + cp.CheckpointID.String(),
114→						Timestamp:        cp.CreatedAt,
115→						IsTaskCheckpoint: cp.IsTask,
116→						ToolUseID:        cp.ToolUseID,
117→					}},
118→				}
119→			}
120→		}
121→	}
122→
123→	// Check for additional sessions
124→	strat := NewManualCommitStrategy()
125→	if additionalSessions, err := strat.GetAdditionalSessions(ctx); err == nil {
126→		for _, addSession := range additionalSessions {
127→			if addSession == nil {
128→				continue
129→			}
130→			if existing, ok := sessionMap[addSession.ID]; ok {
131→				// Merge checkpoints - deduplicate by CheckpointID
132→				existingCPIDs := make(map[string]bool)
133→				for _, cp := range existing.Checkpoints {
134→					existingCPIDs[cp.CheckpointID.String()] = true
135→				}
136→				for _, cp := range addSession.Checkpoints {
137→					if !existingCPIDs[cp.CheckpointID.String()] {
138→						existing.Checkpoints = append(existing.Checkpoints, cp)
139→					}
140→				}
141→				// Update start time if additional session is older
142→				if addSession.StartTime.Before(existing.StartTime) {
143→					existing.StartTime = addSession.StartTime
144→				}
145→				// Use description from additional source if existing is empty
146→				if existing.Description == "" || existing.Description == NoDescription {
147→					existing.Description = addSession.Description
148→				}
149→			} else {
150→				// New session from additional source
151→				sessionMap[addSession.ID] = addSession
152→			}
153→		}
154→	}
155→
156→	// Convert map to slice
157→	sessions := make([]Session, 0, len(sessionMap))
158→	for _, session := range sessionMap {
159→		// Sort checkpoints within each session by timestamp (most recent first)
160→		sort.Slice(session.Checkpoints, func(i, j int) bool {
161→			return session.Checkpoints[i].Timestamp.After(session.Checkpoints[j].Timestamp)
162→		})
163→		sessions = append(sessions, *session)
164→	}
165→
166→	// Sort sessions by start time (most recent first)
167→	sort.Slice(sessions, func(i, j int) bool {
168→		return sessions[i].StartTime.After(sessions[j].StartTime)
169→	})
170→
171→	return sessions, nil
172→}
173→
174→// GetSession finds a session by ID (supports prefix matching).
175→// Returns ErrNoSession if no matching session is found.
176→func GetSession(ctx context.Context, sessionID string) (*Session, error) {
177→	sessions, err := ListSessions(ctx)
178→	if err != nil {
179→		return nil, err
180→	}
181→	return findSessionByID(sessions, sessionID)
182→}
183→
184→// getDescriptionForCheckpoint reads the description for a checkpoint from the entire/checkpoints/v1 branch.
185→// It reads from the latest session subdirectory in the new storage format.
186→func getDescriptionForCheckpoint(repo *git.Repository, checkpointID id.CheckpointID) string {
187→	tree, err := GetMetadataBranchTree(repo)
188→	if err != nil {
189→		return NoDescription
190→	}
191→
192→	// Get the checkpoint tree
193→	checkpointTree, err := tree.Tree(checkpointID.Path())
194→	if err != nil {
195→		return NoDescription
196→	}
197→
198→	// Read root metadata.json to get session count and sessions map
199→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
200→	if err != nil {
201→		return NoDescription
202→	}
203→
204→	content, err := metadataFile.Contents()
205→	if err != nil {
206→		return NoDescription
207→	}
208→
209→	var summary checkpoint.CheckpointSummary
210→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
211→		return NoDescription
212→	}
213→
214→	// Find the first session's prompt/context path
215→	// Try to use the latest session for description (0-based indexing)
216→	sessionDir := "0"
217→	if len(summary.Sessions) > 0 {
218→		sessionDir = strconv.Itoa(len(summary.Sessions) - 1) // Use latest session
219→	}
220→
221→	sessionTree, err := checkpointTree.Tree(sessionDir)
222→	if err != nil {
223→		return NoDescription
224→	}
225→
226→	return getSessionDescriptionFromTree(sessionTree, "")
227→}
228→
229→// findSessionByID finds a session by exact ID or prefix match.
230→func findSessionByID(sessions []Session, sessionID string) (*Session, error) {
231→	for _, session := range sessions {
232→		if session.ID == sessionID || strings.HasPrefix(session.ID, sessionID) {
233→			return &session, nil
234→		}
235→	}
236→	return nil, ErrNoSession
237→}
