395→// Helper function to create a test metadata branch with a multi-session checkpoint
396→func createTestMultiSessionCheckpoint(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID, primarySessionID string, allSessionIDs []string) {
397→	t.Helper()
398→
399→	entries := make(map[string]object.TreeEntry)
400→	checkpointPath := checkpointID.Path()
401→
402→	// Create session-level metadata for each session (0-based indexing)
403→	var sessionFilePaths []checkpoint.SessionFilePaths
404→	for i, sessionID := range allSessionIDs {
405→		sessionDir := strconv.Itoa(i) // 0-based: 0, 1, 2, ...
406→		sessionMetadata := checkpoint.CommittedMetadata{
407→			CheckpointID: checkpointID,
408→			SessionID:    sessionID,
409→			CreatedAt:    time.Now(),
410→		}
411→		sessionMetadataJSON, err := json.Marshal(sessionMetadata)
412→		if err != nil {
413→			t.Fatalf("failed to marshal session metadata: %v", err)
414→		}
415→		sessionMetadataBlobHash, err := checkpoint.CreateBlobFromContent(repo, sessionMetadataJSON)
416→		if err != nil {
417→			t.Fatalf("failed to create session metadata blob: %v", err)
418→		}
419→		sessionMetadataPath := checkpointPath + "/" + sessionDir + "/" + paths.MetadataFileName
420→		entries[sessionMetadataPath] = object.TreeEntry{
421→			Name: sessionMetadataPath,
422→			Mode: filemode.Regular,
423→			Hash: sessionMetadataBlobHash,
424→		}
425→		// Use absolute paths with leading "/" as per new format
426→		sessionFilePaths = append(sessionFilePaths, checkpoint.SessionFilePaths{
427→			Metadata: "/" + checkpointPath + "/" + sessionDir + "/" + paths.MetadataFileName,
428→		})
429→	}
430→
431→	// Create root CheckpointSummary with Sessions array (using absolute paths)
432→	summary := checkpoint.CheckpointSummary{
433→		CheckpointID: checkpointID,
434→		Sessions:     sessionFilePaths,
435→	}
436→	summaryJSON, err := json.Marshal(summary)
437→	if err != nil {
438→		t.Fatalf("failed to marshal summary: %v", err)
439→	}
440→	summaryBlobHash, err := checkpoint.CreateBlobFromContent(repo, summaryJSON)
441→	if err != nil {
442→		t.Fatalf("failed to create summary blob: %v", err)
443→	}
444→	entries[checkpointPath+"/"+paths.MetadataFileName] = object.TreeEntry{
445→		Name: checkpointPath + "/" + paths.MetadataFileName,
446→		Mode: filemode.Regular,
447→		Hash: summaryBlobHash,
448→	}
449→
450→	// Build tree
451→	treeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
452→	if err != nil {
453→		t.Fatalf("failed to build tree: %v", err)
454→	}
455→
456→	// Create orphan commit
457→	now := time.Now()
458→	sig := object.Signature{
459→		Name:  "Test",
460→		Email: "test@test.com",
461→		When:  now,
462→	}
463→	commit := &object.Commit{
464→		TreeHash:  treeHash,
465→		Author:    sig,
466→		Committer: sig,
467→		Message:   "Multi-session checkpoint\n\n" + trailers.SessionTrailerKey + ": " + primarySessionID,
468→	}
469→
470→	commitObj := repo.Storer.NewEncodedObject()
471→	if err := commit.Encode(commitObj); err != nil {
472→		t.Fatalf("failed to encode commit: %v", err)
473→	}
474→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
475→	if err != nil {
476→		t.Fatalf("failed to store commit: %v", err)
477→	}
478→
479→	// Create branch reference
480→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
481→	ref := plumbing.NewHashReference(refName, commitHash)
482→	if err := repo.Storer.SetReference(ref); err != nil {
483→		t.Fatalf("failed to create branch: %v", err)
484→	}
485→}
